#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# 用途：这台机器上 gh CLI 已经装好并登录过了，本向导只收尾「安装本身之外」
# 那几件必须人来做的事：确认 PATH 生效、复核登录与 scope、设置 git 全局身份、
# 把当前目录变成仓库并关联 GitHub 远端、最后验收。
#
# 运行：在 Git Bash 里执行  bash setup-gh-cli.sh
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

# The library's ask() offers the previous run's answer as the default, read
# from ENV_FILE. Keep that state file in $HOME: nothing here is a project
# setting, and the project directory must stay clean. Every value this wizard
# really persists lands in gh's own keyring or in `git config --global`.
ENV_FILE="$HOME/.setup-gh-cli.state"

# Self-locating: this script sits at the repo root, so the project directory is
# its own directory no matter where the human invokes it from.
PROJECT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"

# Resolve both binaries even when this shell's PATH is stale — which is the
# whole reason this wizard exists, so it must not depend on PATH being right.
GH_BIN=""
if command -v gh >/dev/null 2>&1; then
  GH_BIN="$(command -v gh)"
elif [[ -x "/c/Program Files/GitHub CLI/gh.exe" ]]; then
  GH_BIN="/c/Program Files/GitHub CLI/gh.exe"
fi
GIT_BIN="$(command -v git || true)"
if [[ -z "$GIT_BIN" && -x "/c/Program Files/Git/cmd/git.exe" ]]; then
  GIT_BIN="/c/Program Files/Git/cmd/git.exe"
fi

ghx()  { "$GH_BIN" "$@"; }
gitx() { "$GIT_BIN" "$@"; }

banner "GitHub CLI 收尾与验收"

# ── Stage 1: install + PATH ───────────────────────────────────────────────
stage "确认安装 + 让 PATH 生效"
say "gh 装没装、当前 shell 看不看得见它 —— 这是两件不同的事。"

if [[ -x "/c/Program Files/GitHub CLI/gh.exe" ]]; then
  note "✓ 安装文件在位：C:\\Program Files\\GitHub CLI\\gh.exe"
else
  warn "在 C:\\Program Files\\GitHub CLI\\gh.exe 没找到 gh.exe"
  open_url "https://cli.github.com/"
  step "用 winget 装：winget install --id GitHub.cli  （或从上面的页面下载安装包）"
  step "装完后重新运行本脚本。"
  SKIPPED+=("gh CLI 安装")
  pause "按 Enter 结束"
  finish
  exit 0
fi

if [[ -n "$GIT_BIN" ]]; then
  note "✓ $("$GIT_BIN" --version)"
else
  warn "找不到 git —— gh 需要 git 才能做仓库操作。"
  open_url "https://git-scm.com/download/win"
  step "装 Git for Windows，装完重新运行本脚本。"
  SKIPPED+=("git 安装")
  pause "按 Enter 结束"
  finish
  exit 0
fi

say ""
say "版本："
"$GH_BIN" --version || true

say ""
if command -v gh >/dev/null 2>&1; then
  note "✓ 这个 shell 的 PATH 里能找到 gh（$(command -v gh)）"
else
  warn "这个 shell 的 PATH 里没有 gh —— 它是一个「PATH 更新之前」就启动的旧进程。"
  note "机器级 PATH 已经包含下面两条，重启进程即生效，不用重装："
  note "    C:\\Program Files\\GitHub CLI\\"
  note "    C:\\Program Files\\Git\\cmd"
  step "完全退出并重新启动 DeepSeek Harness 和所有终端窗口（新开标签页不算）。"
  step "重启后再跑一次本脚本，这一步就会变成 ✓。"
  note "本次先用绝对路径继续往下走：$GH_BIN"
  pause "明白了，先继续（稍后自己去重启）"
fi

# ── Stage 2: auth + scopes ────────────────────────────────────────────────
stage "gh 登录与 scope 复核"
say "目标账号：github.com；git 操作用 https（凭据由 gh 代管）。"
say ""

if "$GH_BIN" auth status >/dev/null 2>&1; then
  "$GH_BIN" auth status || true
  say ""
  note "已经登录，不必重走浏览器流程。"
  if confirm "要不要重新登录（换账号 / 补 scope）？"; then
    open_url "https://github.com/login/device"
    step "终端会显示一个 one-time code，粘到刚打开的页面里，然后授权。"
    "$GH_BIN" auth login --web --git-protocol https || true
  fi
else
  warn "尚未登录。"
  open_url "https://github.com/login/device"
  step "终端会显示一个 one-time code，粘到刚打开的页面里，然后授权。"
  "$GH_BIN" auth login --web --git-protocol https || true
fi

GH_USER="$("$GH_BIN" api user --jq .login 2>/dev/null || true)"
if [[ -z "$GH_USER" ]]; then
  GH_USER="$("$GH_BIN" auth status 2>&1 | sed -n 's/.*account \([^ ]*\).*/\1/p' | head -n1 || true)"
fi
if [[ -z "$GH_USER" ]]; then
  warn "没拿到账号名；后面的阶段可能失败，先按 Ctrl-C 处理好登录再重跑。"
  SKIPPED+=("gh 登录")
else
  note "✓ 当前账号：$GH_USER"
fi
note "本阶段不产生需要保存的值：token 存在系统凭据库（keyring）里，由 gh 自己管。"

# ── Stage 3: git global identity ──────────────────────────────────────────
stage "设置 git 全局身份"
say "现在 user.name / user.email 是空的，任何提交都会报 Author identity unknown。"
say ""

DEFAULT_NAME="$("$GH_BIN" api user --jq '.name // .login' 2>/dev/null || true)"
DEFAULT_EMAIL="$("$GH_BIN" api user --jq '"\(.id)+\(.login)@users.noreply.github.com"' 2>/dev/null || true)"
[[ -n "$DEFAULT_NAME" ]]  || DEFAULT_NAME="$GH_USER"
[[ -n "$DEFAULT_EMAIL" ]] || DEFAULT_EMAIL=""

note "现在：user.name = $("$GIT_BIN" config --global user.name || true)"
note "      user.email = $("$GIT_BIN" config --global user.email || true)"
say ""
step "user.name 是提交里显示的署名，随便填，可随时改。"
ask GIT_USER_NAME "user.name（默认 $DEFAULT_NAME）:"
[[ -n "$GIT_USER_NAME" ]] || GIT_USER_NAME="$DEFAULT_NAME"

step "user.email 建议用 GitHub 的 noreply 地址，避免把真实邮箱写进公开提交历史。"
ask GIT_USER_EMAIL "user.email（默认 $DEFAULT_EMAIL）:"
[[ -n "$GIT_USER_EMAIL" ]] || GIT_USER_EMAIL="$DEFAULT_EMAIL"

if [[ -z "$GIT_USER_NAME" || -z "$GIT_USER_EMAIL" ]]; then
  warn "姓名或邮箱为空，跳过写入。重跑本脚本再填一次。"
  SKIPPED+=("git 全局身份")
else
  "$GIT_BIN" config --global user.name  "$GIT_USER_NAME"
  "$GIT_BIN" config --global user.email "$GIT_USER_EMAIL"
  write_env GIT_USER_NAME  "$GIT_USER_NAME"
  write_env GIT_USER_EMAIL "$GIT_USER_EMAIL"
  note "✓ 写入 git config --global（不是本仓库的局部配置）"
fi

# Belt and braces: point git's credential helper at gh for github.com/gist.
# Already done on this machine; re-running is idempotent.
if confirm "顺便重跑 gh auth setup-git（让 git 用 gh 的凭据，幂等）？"; then
  "$GH_BIN" auth setup-git || warn "gh auth setup-git 失败，稍后手动重跑"
fi

# ── Stage 4: make this directory a repo + GitHub remote ───────────────────
stage "把本目录变成仓库并关联 GitHub 远端"
say "当前目录：$PROJECT_DIR"
cd "$PROJECT_DIR"

if [[ -d .git ]]; then
  note "✓ 已经是 git 仓库，跳过 git init"
else
  if confirm "在这里执行 git init -b main？"; then
    "$GIT_BIN" init -b main
  else
    SKIPPED+=("git init")
  fi
fi

if [[ -d .git ]]; then
  if "$GIT_BIN" rev-parse HEAD >/dev/null 2>&1; then
    note "✓ 已有提交历史：$("$GIT_BIN" log --oneline -1 || true)"
  else
    step "先把现有文件做成第一个提交。"
    "$GIT_BIN" add -A
    "$GIT_BIN" commit -m "chore: initial commit" || warn "提交失败（检查上面的身份配置）"
  fi
fi

if [[ ! -d .git ]]; then
  warn "这里还不是 git 仓库，跳过远端部分。先 git init 再重跑本脚本。"
  SKIPPED+=("GitHub 远端仓库")
elif ! "$GIT_BIN" remote get-url origin >/dev/null 2>&1; then
  if [[ -z "$GH_USER" ]]; then
    warn "拿不到 gh 账号名，跳过创建远端；先按 Stage 2 登录好再重跑。"
    SKIPPED+=("GitHub 远端仓库")
  else
    say ""
    say "要建一个 GitHub 远端仓库。仓库名只能用字母数字和 . _ -（中文目录名不能直接当仓库名）。"
    ask REPO_NAME "仓库名（默认 jifen-lingqu）:"
    [[ -n "$REPO_NAME" ]] || REPO_NAME="jifen-lingqu"
    REPO_OWNER="$GH_USER"

    VISIBILITY="--private"
    if confirm "建成公开仓库吗？（不选＝私有；公开后全世界可见，且不好收回）"; then
      VISIBILITY="--public"
    fi
    if [[ "$VISIBILITY" == "--public" ]]; then
      note "将创建：$REPO_OWNER/$REPO_NAME （公开）"
    else
      note "将创建：$REPO_OWNER/$REPO_NAME （私有）"
    fi

    if confirm "确认创建并推送当前目录？"; then
      if "$GH_BIN" repo view "$REPO_OWNER/$REPO_NAME" >/dev/null 2>&1; then
        note "远端仓库已存在，只加 origin 不重建"
        "$GIT_BIN" remote add origin "https://github.com/$REPO_OWNER/$REPO_NAME.git" \
          || warn "加 origin 失败，可能已存在同名 remote"
      else
        "$GH_BIN" repo create "$REPO_OWNER/$REPO_NAME" "$VISIBILITY" \
          --source=. --remote=origin --push \
          || warn "gh repo create 失败，检查网络或仓库名是否被占用"
      fi
      "$GIT_BIN" push -u origin main || warn "推送失败；远端建好后可手动 git push -u origin main"
    else
      SKIPPED+=("GitHub 远端仓库")
    fi
  fi
else
  note "✓ origin 已存在：$("$GIT_BIN" remote get-url origin || true)"
  "$GIT_BIN" push -u origin main || warn "推送失败；可手动重试"
fi

# ── Stage 5: verification ─────────────────────────────────────────────────
stage "最终验收"
say "逐条确认 gh → git → GitHub 全链路通。"
say ""

note "gh 版本      : $("$GH_BIN" --version | head -n1)"
if "$GH_BIN" auth status >/dev/null 2>&1; then
  note "gh 登录      : ✓ $GH_USER"
else
  warn "gh 登录      : ✗ 未登录"
fi
note "API 身份     : $("$GH_BIN" api user --jq .login 2>/dev/null || echo '不可用')"
note "git          : $("$GIT_BIN" --version || true)"
note "user.name    : $("$GIT_BIN" config --global user.name || true)"
note "user.email   : $("$GIT_BIN" config --global user.email || true)"
say ""
note "仓库状态     : $("$GIT_BIN" status -sb | head -n1 || true)"
note "最近提交     : $("$GIT_BIN" log --oneline -1 || true)"
if "$GIT_BIN" remote get-url origin >/dev/null 2>&1; then
  note "远端         : $("$GIT_BIN" remote get-url origin || true)"
  step "用一次只读的 ls-remote 证明凭据可用（不会改动任何东西）。"
  if "$GIT_BIN" ls-remote --heads origin >/dev/null 2>&1; then
    note "✓ 凭据连通，ls-remote 成功"
  else
    warn "ls-remote 失败：凭据或远端有问题"
    SKIPPED+=("远端凭据连通性验证")
  fi
else
  warn "还没有 origin 远端 —— gh 本身可用，只是这个目录还没接上 GitHub"
  SKIPPED+=("GitHub 远端关联")
fi

say ""
note "提醒：本会话（安装前就启动的进程）PATH 里仍没有 gh/git。"
note "重启 DeepSeek Harness 之后，agent 才能直接调用 gh，不再需要绝对路径。"

finish
